namespace RaceDayAPI.Models
{
    public class User { public int UserId { get; set; } public string FirstName { get; set; } = ""; public string LastName { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = ""; public string? Phone { get; set; } public DateTime CreatedAt { get; set; } }
    public class Event { public int EventId { get; set; } public int OrganizerId { get; set; } public string EventName { get; set; } = ""; public string? Description { get; set; } public DateTime EventDate { get; set; } public string? Location { get; set; } public int MaxParticipants { get; set; } public string Status { get; set; } = "Open"; public double? Distance { get; set; } public string? EventType { get; set; } public DateTime CreatedAt { get; set; } public User? Organizer { get; set; } public ICollection<EventCategory> EventCategories { get; set; } = new List<EventCategory>(); }
    public class Category { public int CategoryId { get; set; } public string CategoryName { get; set; } = ""; public string? Description { get; set; } public ICollection<EventCategory> EventCategories { get; set; } = new List<EventCategory>(); }
    public class EventCategory { public int EventId { get; set; } public int CategoryId { get; set; } public decimal? EntryFee { get; set; } public int? Capacity { get; set; } public Event? Event { get; set; } public Category? Category { get; set; } }
    public class Enrolment { public int EnrolmentId { get; set; } public int ParticipantId { get; set; } public int EventId { get; set; } public int CategoryId { get; set; } public DateTime EnrolledAt { get; set; } public string Status { get; set; } = "Confirmed"; public User? Participant { get; set; } public Event? Event { get; set; } }
    public class Result { public int ResultId { get; set; } public int EnrolmentId { get; set; } public TimeSpan? FinishTime { get; set; } public int? Position { get; set; } public int? Score { get; set; } public string ResultStatus { get; set; } = "Finished"; public DateTime RecordedAt { get; set; } public Enrolment? Enrolment { get; set; } }
}
